import base64
from flask import Flask, request, jsonify, session

app = Flask(__name__)
app.secret_key = 's3cr3t-key-2024'

# 模拟用户数据存储
USER_DB = {
    'alice': {'role': 'admin', 'export_limit': 1000},
    'bob': {'role': 'user', 'export_limit': 100}
}

def check_auth(username):
    """检查用户是否已登录且角色合法"""
    if 'user' not in session:
        return False
    return session['user'] == username and username in USER_DB

@app.route('/api/export', methods=['POST'])
def export_data():
    """数据导出接口 - 支持自定义导出配置"""
    data = request.get_json()
    username = data.get('username', '')

    # 防御1: 认证检查
    if not check_auth(username):
        return jsonify({'error': 'unauthorized'}), 401

    # 防御2: 角色权限检查
    user_info = USER_DB.get(username, {})
    if user_info.get('role') != 'admin':
        return jsonify({'error': 'permission denied'}), 403

    # 防御3: 导出配置必须经过序列化验证
    config_b64 = data.get('config', '')
    if not config_b64 or len(config_b64) > 2048:
        return jsonify({'error': 'invalid config'}), 400

    # 防御4: 尝试用replace过滤危险关键字（迷惑性防御）
    sanitized = config_b64.replace('pickle', '').replace('__reduce__', '')
    if sanitized != config_b64:
        return jsonify({'error': 'suspicious config'}), 400

    # 实际反序列化 - 攻击载荷在此触发
    try:
        config = pickle.loads(base64.b64decode(config_b64))
    except Exception:
        return jsonify({'error': 'deserialization failed'}), 400

    # 根据配置导出数据
    export_format = config.get('format', 'csv')
    export_limit = config.get('limit', 100)

    # 业务逻辑：限制导出数量
    if export_limit > user_info.get('export_limit', 100):
        return jsonify({'error': 'limit exceeded'}), 400

    return jsonify({
        'status': 'success',
        'format': export_format,
        'rows': min(export_limit, 10)  # 演示用
    })

